scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 checkbox, checkcombobox, input, inputCalendar, AutoComplete, select, radio, multiselect 관련 버튼을 각각 클릭하여 개발자모드 콘솔에서 확인한다. 
    //1. After running the sample file, click on the checkbox, checkcombobox, input, inputCalendar, AutoComplete, select, radio, and multiselect buttons to check in the developer mode console.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger7').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger8').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger9').click()");
    // verify step 1. callerId, type, value 값들이 각각 반환되어 보여진다.(첨부 이미지 참고)
    //1. CallerId, type and value are returned and shown (see attached image).
    //checkbox1
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkbox1').validateObject().callerId", "mf_checkbox1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkbox1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkbox1').validateObject().value == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //checkcombobox
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1').validateObject().callerId", "mf_checkcombobox1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1').validateObject().value == ''", "true");
    //input
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').validateObject().callerId", "mf_input1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').validateObject().value == ''", "true");
    //inputCalendar
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1').validateObject().callerId", "mf_inputCalendar1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar1').validateObject().value == ''", "true");
    //autocomplete
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1').validateObject().callerId", "mf_autoComplete1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1').validateObject().value == ''", "true");
    //select
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').validateObject().callerId", "mf_selectbox1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').validateObject().value == ''", "true");
    //radio
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('radio1').validateObject().callerId", "mf_radio1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('radio1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('radio1').validateObject().value == ''", "true");
    //multiselect
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('multiselect1').validateObject().callerId", "mf_multiselect1");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('multiselect1').validateObject().type", "mandatory");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('multiselect1').validateObject().value == ''", "true");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
}
